CREATE TABLE "pricing_plans" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"model" "pricing_model" NOT NULL,
	"commission_rate" numeric(5, 2) DEFAULT 0 NOT NULL,
	"monthly_fee_npr" numeric(12, 2) DEFAULT 0 NOT NULL,
	"duration_cycles" integer,
	"is_offered" boolean DEFAULT true NOT NULL,
	"is_default" boolean DEFAULT false NOT NULL,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "pricing_plans_name_check" CHECK (btrim("pricing_plans"."name") <> ''),
	CONSTRAINT "pricing_plans_commission_check" CHECK (("pricing_plans"."model"::text = 'COMMISSION' AND "pricing_plans"."commission_rate" > 0 AND "pricing_plans"."commission_rate" <= 100) OR ("pricing_plans"."model"::text <> 'COMMISSION' AND "pricing_plans"."commission_rate" = 0)),
	CONSTRAINT "pricing_plans_fee_check" CHECK (("pricing_plans"."model"::text = 'SUBSCRIPTION' AND "pricing_plans"."monthly_fee_npr" > 0) OR ("pricing_plans"."model"::text <> 'SUBSCRIPTION' AND "pricing_plans"."monthly_fee_npr" = 0)),
	CONSTRAINT "pricing_plans_duration_check" CHECK (("pricing_plans"."model"::text = 'FREE') = ("pricing_plans"."duration_cycles" IS NOT NULL) AND ("pricing_plans"."duration_cycles" IS NULL OR "pricing_plans"."duration_cycles" > 0)),
	CONSTRAINT "pricing_plans_default_check" CHECK (NOT "pricing_plans"."is_default" OR ("pricing_plans"."model"::text = 'COMMISSION' AND "pricing_plans"."is_offered"))
);
